record CreateOrderRequest(long productId, int quantity) {}
record OrderResponse(long id) {}
@RestController
@RequestMapping("/orders")
class OrderController {
    private final OrderService service;
    OrderController(OrderService service) { this.service = service; }
    @PostMapping
    OrderResponse create(@RequestBody CreateOrderRequest request) {
        return new OrderResponse(service.place(request.productId(), request.quantity()));
    }
}

data class CreateOrderRequest(val productId: Long, val quantity: Int)
data class OrderResponse(val id: Long)
@RestController
@RequestMapping("/orders")
class OrderController(private val service: OrderService) {
    @PostMapping
    fun create(@RequestBody request: CreateOrderRequest) =
        OrderResponse(service.place(request.productId, request.quantity))
}

