@RestControllerAdvice
class ApiErrors {
    @ExceptionHandler(OutOfStock.class)
    ProblemDetail soldOut(OutOfStock error) {
        var problem = ProblemDetail.forStatusAndDetail(
            HttpStatus.CONFLICT, "요청한 수량을 확보할 수 없습니다.");
        problem.setTitle("재고 부족");
        problem.setProperty("code", "OUT_OF_STOCK");
        return problem;
    }
}

